1	// tb_csr_if ΓÇö CSR register matrix through the Avalon-MM and AXI4-Lite front-ends (issue #11).
2	//
3	// The native-bus matrix is proven in tb_csr. This TB re-runs one SHARED matrix body through
4	// scope_avalon and scope_axil (a `BUS`-parameterized leg + bus-abstract bwrite/bread tasks), so
5	// the thin adapters are proven to carry every register class, the CTRL strobes, the cfg_err
6	// lockout, and ΓÇö the place thin adapters break ΓÇö the BUF_DATA pop-on-read side effect.
7	//
8	// BUF_DATA check without a golden buffer: sample_data is a free-running 8-bit counter stored by
9	// a contiguous, every-cycle write pointer, so buffer[addr] is linear in addr; DEPTH pops must
10	// return v[i] == (v[0]+i) mod 256. A double-pop or missed pop breaks the run.
11	//
12	/* verilator lint_off DECLFILENAME */
13	// waiver: helper module deliberately co-located in its TB's file (not a standalone unit)
14	module tb_csr_if_leg
15	  import scope_pkg::*;
16	#(
17	    parameter int unsigned BUS        = 1,     // 1 = Avalon-MM, 2 = AXI4-Lite
18	    parameter int unsigned PROBE_W    = 8,
19	    parameter int unsigned DEPTH_LOG2 = 8,
20	    parameter string       NAME       = "leg"
21	) (
22	    output bit done,
23	    output int unsigned errs
24	);
25	  localparam int unsigned NUM_CMP = 4, SEQ_STAGES = 4, TS_W = 48;
26	  localparam int unsigned DEPTH = 1 << DEPTH_LOG2;
27	
28	  logic clk = 1'b0;
29	  always #5 clk <= ~clk;
30	  logic rst = 1'b1;
31	
32	  // native CSR bus (adapter -> scope_csr)
33	  logic [7:0]  csr_addr;
34	  logic [31:0] csr_wdata;
35	  logic        csr_write, csr_read;
36	  logic [31:0] csr_rdata;
37	
38	  // core wiring
39	  logic arm, disarm, force_trig;
40	  logic [DEPTH_LOG2-1:0] pretrig;
41	  logic [7:0] windows, windows_done;
42	  logic rle_enable;
43	  logic [2:0] state;
44	  logic triggered, wrapped, armed, cfg_err;
45	  logic [DEPTH_LOG2-1:0] trig_index;
46	  logic [TS_W-1:0] ts, ts_at_trig;
47	  logic [DEPTH_LOG2-1:0] buf_rd_addr;
48	  logic [PROBE_W-1:0] buf_rd_data;
49	  logic [7:0] win_rd_addr;
50	  logic [DEPTH_LOG2:0] win_rd_data;
51	  logic [NUM_CMP*PROBE_W-1:0] cmp_mask, cmp_value, cmp_edge_mask, cmp_edge_pol;
52	  logic [31:0] trig_combine;
53	  logic [SEQ_STAGES*32-1:0] seq_cnt;
54	
55	  // sample stream: free-running counter, valid every cycle during capture
56	  logic [PROBE_W-1:0] sample_data = '0;
57	  logic sample_valid = 1'b0;
58	  always_ff @(posedge clk) if (sample_valid) sample_data <= sample_data + 1'b1;
59	
60	  // ---- Avalon-MM front-end signals ----
61	  logic [7:0]  av_addr = '0;
62	  logic        av_read = 1'b0, av_write = 1'b0;
63	  logic [31:0] av_wdata = '0, av_rdata;
64	  logic        av_wait;
65	
66	  // ---- AXI4-Lite front-end signals ----
67	  logic [9:0]  ax_awaddr = '0, ax_araddr = '0;
68	  logic        ax_awvalid = 1'b0, ax_wvalid = 1'b0, ax_bready = 1'b0;
69	  logic        ax_arvalid = 1'b0, ax_rready = 1'b0;
70	  logic [31:0] ax_wdata = '0, ax_rdata;
71	  logic        ax_awready, ax_wready, ax_bvalid, ax_arready, ax_rvalid;
72	  logic [1:0]  ax_bresp, ax_rresp;
73	
74	  generate
75	    if (BUS == 1) begin : g_avalon
76	      scope_avalon u_if (
77	          .address(av_addr), .read(av_read), .readdata(av_rdata),
78	          .write(av_write), .writedata(av_wdata), .waitrequest(av_wait),
79	          .csr_addr(csr_addr), .csr_wdata(csr_wdata), .csr_write(csr_write),
80	          .csr_read(csr_read), .csr_rdata(csr_rdata));
81	      // AXI outputs unused in this leg ΓÇö tie off (no UNDRIVEN)
82	      assign ax_awready = 1'b0; assign ax_wready = 1'b0; assign ax_bvalid = 1'b0;
83	      assign ax_arready = 1'b0; assign ax_rvalid = 1'b0;
84	      assign ax_bresp = 2'b0;  assign ax_rresp = 2'b0;  assign ax_rdata = 32'b0;
85	    end else begin : g_axil
86	      scope_axil u_if (
87	          .clk(clk), .rst(rst),
88	          .awaddr(ax_awaddr), .awvalid(ax_awvalid), .awready(ax_awready),
89	          .wdata(ax_wdata), .wstrb(4'hF), .wvalid(ax_wvalid), .wready(ax_wready),
90	          .bresp(ax_bresp), .bvalid(ax_bvalid), .bready(ax_bready),
91	          .araddr(ax_araddr), .arvalid(ax_arvalid), .arready(ax_arready),
92	          .rdata(ax_rdata), .rresp(ax_rresp), .rvalid(ax_rvalid), .rready(ax_rready),
93	          .csr_addr(csr_addr), .csr_wdata(csr_wdata), .csr_write(csr_write),
94	          .csr_read(csr_read), .csr_rdata(csr_rdata));
95	      // Avalon outputs unused in this leg ΓÇö tie off (no UNDRIVEN)
96	      assign av_rdata = 32'b0; assign av_wait = 1'b0;
97	    end
98	  endgenerate
99	
100	  scope_csr #(.PROBE_W(PROBE_W), .DEPTH_LOG2(DEPTH_LOG2), .NUM_CMP(NUM_CMP),
101	              .SEQ_STAGES(SEQ_STAGES), .RLE_EN(1'b0), .TS_W(TS_W)) u_csr (
102	      .clk(clk), .rst(rst),
103	      .csr_addr(csr_addr), .csr_wdata(csr_wdata), .csr_write(csr_write),
104	      .csr_read(csr_read), .csr_rdata(csr_rdata),
105	      .arm(arm), .disarm(disarm), .force_trig(force_trig), .pretrig(pretrig),
106	      .windows(windows), .rle_enable(rle_enable),
107	      /* verilator lint_off PINCONNECTEMPTY */
108	      .decim(), .qual_en(), .qual_sel(),        // SMPL_CTRL outputs (#17/#20) unused in this TB
109	      /* verilator lint_on PINCONNECTEMPTY */
110	      .state(state), .triggered(triggered),
111	      .wrapped(wrapped), .windows_done(windows_done), .trig_index(trig_index),
112	      .ts(ts), .ts_at_trig(ts_at_trig), .buf_rd_addr(buf_rd_addr), .buf_rd_data(buf_rd_data),
113	      .win_rd_addr(win_rd_addr), .win_rd_data(win_rd_data),
114	      .cmp_mask(cmp_mask), .cmp_value(cmp_value), .cmp_edge_mask(cmp_edge_mask),
115	      .cmp_edge_pol(cmp_edge_pol), .trig_combine(trig_combine), .seq_cnt(seq_cnt),
116	      .cfg_err(cfg_err));
117	
118	  scope_core #(.PROBE_W(PROBE_W), .DEPTH_LOG2(DEPTH_LOG2), .TS_W(TS_W)) u_core (
119	      .clk(clk), .rst(rst), .sample_data(sample_data), .sample_valid(sample_valid),
120	      .trig(force_trig), .arm(arm), .disarm(disarm), .pretrig(pretrig), .windows(windows),
121	      .state(state), .triggered(triggered), .wrapped(wrapped), .windows_done(windows_done),
122	      .trig_index(trig_index), .armed(armed), .rd_addr(buf_rd_addr), .rd_data(buf_rd_data),
123	      .win_rd_addr(win_rd_addr), .win_rd_data(win_rd_data), .ts(ts), .ts_at_trig(ts_at_trig));
124	
125	  // trigger config outputs are unused here (matrix only reads them back via CSR)
126	  // one bus is active per leg; sink the other bus's TB-driven / adapter signals so an unused
127	  // generate branch does not trip UNUSEDSIGNAL (both sets referenced ΓçÆ -Wall clean either way).
128	  wire _unused = &{1'b0, cmp_mask, cmp_value, cmp_edge_mask, cmp_edge_pol, trig_combine,
129	                   seq_cnt, armed, triggered, wrapped, trig_index, ts, ts_at_trig,
130	                   windows_done, rle_enable, disarm, arm,
131	                   av_addr, av_read, av_write, av_wdata, av_rdata, av_wait, cfg_err, rd,
132	                   ax_awaddr, ax_araddr, ax_awvalid, ax_wvalid, ax_bready, ax_arvalid,
133	                   ax_rready, ax_wdata, ax_rdata, ax_awready, ax_wready, ax_bvalid,
134	                   ax_arready, ax_rvalid, ax_bresp, ax_rresp};
135	
136	  int unsigned errors = 0;
137	  task automatic fail(input string m);
138	    $display("TB_RESULT: FAIL"); $display("[%s] %s", NAME, m); errors++;
139	  endtask
140	
141	  // ---- bus-abstract write/read (aw_first: 0 = W first, 1 = AW first, 2 = simultaneous) ----
142	  task automatic bwrite(input logic [7:0] word, input logic [31:0] d, input int aw_first = 2);
143	    if (BUS == 1) begin
144	      @(negedge clk); av_addr = word; av_wdata = d; av_write = 1'b1;
145	      @(posedge clk); #1 av_write = 1'b0;
146	    end else begin
147	      if (aw_first == 1) begin
148	        @(negedge clk); ax_awaddr = {word, 2'b00}; ax_awvalid = 1'b1;
149	        @(negedge clk); ax_wdata = d; ax_wvalid = 1'b1;
150	      end else if (aw_first == 0) begin
151	        @(negedge clk); ax_wdata = d; ax_wvalid = 1'b1;
152	        @(negedge clk); ax_awaddr = {word, 2'b00}; ax_awvalid = 1'b1;
153	      end else begin
154	        @(negedge clk); ax_awaddr = {word, 2'b00}; ax_awvalid = 1'b1; ax_wdata = d; ax_wvalid = 1'b1;
155	      end
156	      // wait for joint accept
157	      do @(posedge clk); while (!(ax_awready && ax_wready));
158	      #1 ax_awvalid = 1'b0; ax_wvalid = 1'b0;
159	      ax_bready = 1'b1;
160	      do @(posedge clk); while (!ax_bvalid);
161	      #1 ax_bready = 1'b0;
162	    end
163	  endtask
164	
165	  task automatic bread(input logic [7:0] word, output logic [31:0] d);
166	    if (BUS == 1) begin
167	      // mirror the native csr_rd phase exactly (read spans one posedge, negedge..negedge) so the
168	      // registered-RAM BUF_DATA pre-fetch is valid ΓÇö scope_avalon is a combinational rename.
169	      @(negedge clk); av_addr = word; av_read = 1'b1;
170	      #2 d = av_rdata;               // combinational readdata, settled, no edge crossed
171	      @(negedge clk); av_read = 1'b0;   // one native csr_read cycle -> one BUF_DATA pop
172	    end else begin
173	      @(negedge clk); ax_araddr = {word, 2'b00}; ax_arvalid = 1'b1;
174	      do @(posedge clk); while (!ax_arready);   // AR accepted -> one csr_read pulse
175	      #1 ax_arvalid = 1'b0; ax_rready = 1'b1;
176	      do @(posedge clk); while (!ax_rvalid);
177	      #1 d = ax_rdata; ax_rready = 1'b0;
178	    end
179	  endtask
180	
181	  task automatic bexpect(input logic [7:0] word, input logic [31:0] want, input string what);
182	    logic [31:0] got; bread(word, got);
183	    if (got !== want) fail($sformatf("%s @%0d: got %h want %h", what, word, got, want));
184	  endtask
185	
186	  logic [31:0] rd, id_val, hwcfg_val;
187	  task automatic run_matrix;
188	    // --- RO registers reject writes and read stable ---
189	    bread(8'(CSR_ID), id_val);
190	    if ((id_val & 32'hFFFF_F000) != SCOPE_ID_MAGIC) fail($sformatf("ID magic %h", id_val));
191	    bwrite(8'(CSR_ID), 32'hDEAD_BEEF); bexpect(8'(CSR_ID), id_val, "ID RO");
192	    bread(8'(CSR_HWCFG), hwcfg_val);
193	    bwrite(8'(CSR_HWCFG), 32'h0); bexpect(8'(CSR_HWCFG), hwcfg_val, "HWCFG RO");
194	
195	    // --- R/W scalar registers walk ---
196	    bwrite(8'(CSR_PRETRIG), 32'h0000_002A); bexpect(8'(CSR_PRETRIG), 32'h2A, "PRETRIG");
197	    bwrite(8'(CSR_WINDOWS), 32'h0000_0003); bexpect(8'(CSR_WINDOWS), 32'h3, "WINDOWS");
198	    bwrite(8'(CSR_RLE_CTRL), 32'h1); bexpect(8'(CSR_RLE_CTRL), 32'h1, "RLE_CTRL RW bit0");
199	    bwrite(8'(CSR_RLE_CTRL), 32'h0); bexpect(8'(CSR_RLE_CTRL), 32'h0, "RLE_CTRL clear");
200	    bwrite(8'(CSR_TRIG_COMBINE), 32'hA5A5_1234); bexpect(8'(CSR_TRIG_COMBINE), 32'hA5A5_1234, "TRIG_COMBINE");
201	    for (int n = 0; n < 4; n++) begin
202	      bwrite(8'(CSR_SEQ_CNT_BASE + n), 32'h1000_0000 + n);
203	      bexpect(8'(CSR_SEQ_CNT_BASE + n), 32'h1000_0000 + n, $sformatf("SEQ_CNT%0d", n));
204	    end
205	
206	    // --- comparator lane window (CMP_SEL selects k+field; lane 0 window) ---
207	    for (int k = 0; k < 4; k++) begin
208	      bwrite(8'(CSR_CMP_SEL), 32'(k));          // field 0 = MASK
209	      bwrite(8'(CSR_CMP_LANE_BASE), 32'hFF & (32'hC3 + k));
210	      bwrite(8'(CSR_CMP_SEL), 32'(k));
211	      bexpect(8'(CSR_CMP_LANE_BASE), 32'hFF & (32'hC3 + k), $sformatf("CMP%0d MASK lane0", k));
212	    end
213	
214	    // --- AXI4-Lite AW/W arrival-order independence (BUS==2) + back-to-back reads ---
215	    if (BUS == 2) begin
216	      bwrite(8'(CSR_PRETRIG), 32'h11, 1);  // AW before W
217	      bexpect(8'(CSR_PRETRIG), 32'h11, "AXI AW-first");
218	      bwrite(8'(CSR_PRETRIG), 32'h22, 0);  // W before AW
219	      bexpect(8'(CSR_PRETRIG), 32'h22, "AXI W-first");
220	      bwrite(8'(CSR_PRETRIG), 32'h33, 2);  // simultaneous
221	      bexpect(8'(CSR_PRETRIG), 32'h33, "AXI simultaneous");
222	      bexpect(8'(CSR_PRETRIG), 32'h33, "AXI back-to-back read");
223	    end
224	
225	    // --- CTRL strobes self-clear (read back 0) ---
226	    bwrite(8'(CSR_CTRL), 32'h1);               // arm strobe
227	    bexpect(8'(CSR_CTRL), 32'h0, "CTRL self-clear");
228	    bwrite(8'(CSR_CTRL), 32'h8);               // soft_rst -> back to IDLE, clears cfg_err
229	    repeat (3) @(posedge clk);
230	
231	    // --- cfg_err lockout through the adapter ---
232	    bwrite(8'(CSR_PRETRIG), 32'h0);
233	    bwrite(8'(CSR_WINDOWS), 32'h1);
234	    bwrite(8'(CSR_CTRL), 32'h1);               // arm (state leaves IDLE)
235	    repeat (4) @(posedge clk);
236	    bwrite(8'(CSR_PRETRIG), 32'h55);           // config write while armed -> ignored + cfg_err
237	    bread(8'(CSR_STATUS), rd);
238	    if (!rd[5]) fail("cfg_err not set on armed config write");
239	    if (state == SCOPE_ST_IDLE) fail("core unexpectedly IDLE during lockout test");
240	    bwrite(8'(CSR_CTRL), 32'h8);               // soft_rst clears cfg_err + disarms
241	    repeat (3) @(posedge clk);
242	    bread(8'(CSR_STATUS), rd);
243	    if (rd[5]) fail("cfg_err not cleared by soft_rst");
244	
245	    // --- BUF_DATA pop-on-read: capture the counter, drain DEPTH samples, expect linear seq ---
246	    sample_valid = 1'b1;
247	    bwrite(8'(CSR_PRETRIG), 32'h0);
248	    bwrite(8'(CSR_WINDOWS), 32'h1);
249	    bwrite(8'(CSR_CTRL), 32'h1);               // arm
250	    fork begin : wait_armed
251	      int g; g = 0;
252	      forever begin @(posedge clk); if (state == SCOPE_ST_ARMED) break; g++;
253	        if (g > 100) begin fail("never reached ARMED"); break; end end
254	    end join
255	    bwrite(8'(CSR_CTRL), 32'h4);               // force_trig
256	    begin : wait_done
257	      int g; g = 0;
258	      forever begin @(posedge clk); if (state == SCOPE_ST_DONE) break; g++;
259	        if (g > 4*DEPTH) begin fail("never reached DONE"); break; end end
260	    end
261	    bwrite(8'(CSR_BUF_CTRL), 32'h1);           // reset drain pointer
262	    begin : drain
263	      // PROBE_W=8 lane is zero-extended into csr_rdata; buffer[addr] is linear in addr, so
264	      // successive pops must be (v0+i) mod 256. A double-pop or missed pop breaks the run.
265	      logic [31:0] v0, vi, want;
266	      bread(8'(CSR_BUF_DATA), v0);
267	      for (int i = 1; i < DEPTH; i++) begin
268	        bread(8'(CSR_BUF_DATA), vi);
269	        want = (v0 + 32'(i)) & 32'hFF;
270	        if (vi !== want)
271	          fail($sformatf("BUF_DATA pop seq @%0d: got %h want %h (v0=%h)", i, vi, want, v0));
272	      end
273	    end
274	    sample_valid = 1'b0;
275	  endtask
276	
277	  initial begin
278	    done = 1'b0; errs = 0;
279	    repeat (4) @(posedge clk); @(negedge clk); rst = 1'b0;
280	    run_matrix;
281	    errs = errors;
282	    if (errors == 0) $display("-- [%s] BUS=%0d matrix + BUF_DATA pop + cfg_err: PASS", NAME, BUS);
283	    done = 1'b1;
284	  end
285	endmodule
286	/* verilator lint_on DECLFILENAME */
287	
288	module tb_csr_if;
289	  bit d_av, d_ax;
290	  int unsigned e_av, e_ax;
291	  tb_csr_if_leg #(.BUS(1), .NAME("avalon")) u_av (.done(d_av), .errs(e_av));
292	  tb_csr_if_leg #(.BUS(2), .NAME("axil"))   u_ax (.done(d_ax), .errs(e_ax));
293	
294	  initial begin
295	    wait (d_av && d_ax);
296	    #20;
297	    if (e_av != 0 || e_ax != 0) begin
298	      $display("TB_RESULT: FAIL");
299	      $fatal(1, "tb_csr_if: avalon errs=%0d axil errs=%0d", e_av, e_ax);
300	    end
301	    $display("TB_RESULT: PASS");
302	    $finish;
303	  end
304	
305	  initial begin
306	    #5_000_000;
307	    $display("TB_RESULT: FAIL");
308	    $display("tb_csr_if: global timeout");
309	    $finish;
310	  end
311	endmodule
312

